import{at as e,n as t,rt as n,yt as r}from"./chunks/framework.ne95vkW4.js";var i=JSON.parse(`{"title":"Components","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/components.md","filePath":"architecture/components.md","lastUpdated":1790055484000}`),a={name:`architecture/components.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to “Components”">​</a></h1><p>This page maps every real module under <code>src/</code> to what it does. It is a companion to <code>overview.md</code>, which covers the request flow, the redirect-based delivery trade-off, and the two required diagrams. Every module and file path below was checked against the code on <code>main</code>, not assumed from names.</p><h2 id="entry-point" tabindex="-1">Entry point <a class="header-anchor" href="#entry-point" aria-label="Permalink to “Entry point”">​</a></h2><h3 id="src-main-rs" tabindex="-1"><code>src/main.rs</code> <a class="header-anchor" href="#src-main-rs" aria-label="Permalink to “src/main.rs”">​</a></h3><p>Builds the Tokio runtime by hand (not <code>#[tokio::main]</code>) so <code>worker_threads</code> can be a runtime value read from <code>TOKIO_WORKER_THREADS</code>, cgroup-aware via <code>modules::utils::cgroup::effective_cpu_count</code> rather than <code>num_cpus::get()</code> directly (a cgroup-limited container otherwise oversizes the runtime for the host&#39;s full core count). Sets the platform <code>System</code> allocator as the global allocator, replacing <code>mimalloc</code>/<code>libmimalloc-sys</code> (#134). Installs a SIGTERM/SIGINT-triggered graceful shutdown with a configurable drain deadline (<code>SHUTDOWN_TIMEOUT_SECS</code>, default 20s — comfortably under Kubernetes&#39; default 30s <code>terminationGracePeriodSeconds</code>).</p><h3 id="src-bin-healthcheck-rs-src-bin-benchmark-rs" tabindex="-1"><code>src/bin/healthcheck.rs</code>, <code>src/bin/benchmark.rs</code> <a class="header-anchor" href="#src-bin-healthcheck-rs-src-bin-benchmark-rs" aria-label="Permalink to “src/bin/healthcheck.rs, src/bin/benchmark.rs”">​</a></h3><p>Two extra binaries: a standalone healthcheck probe, and a load-generating benchmark client (serves fixture images locally and drives the resize endpoint against them — see <code>.bench-baseline/BASELINE.md</code> for how its output feeds the performance numbers cited in <code>overview.md</code>).</p><h2 id="router-and-middleware-—-src-modules-router" tabindex="-1">Router and middleware — <code>src/modules/router/</code> <a class="header-anchor" href="#router-and-middleware-—-src-modules-router" aria-label="Permalink to “Router and middleware — src/modules/router/”">​</a></h2><ul><li><strong><code>router.rs</code></strong> — hand-written route table (<code>build_app</code>): <code>GET /health</code> (unauthenticated, Kubernetes probe target), <code>GET /api/images/files/{key}</code> (unsigned download route), <code>GET /{signature}/{*rest}</code> (the imgproxy-compatible signed resize route, mounted at the root — axum/matchit prefers a literal path segment like <code>api</code>/<code>health</code> over this route&#39;s dynamic first segment, so it never shadows the others), and, only when built with <code>--features otel</code>, <code>GET /metrics</code> behind <code>metrics_auth::require_metrics_auth</code>. There is no <code>gen_server</code>-generated router anywhere in this file or this codebase — see &quot;Removed&quot; below.</li><li><strong><code>middlewares.rs</code></strong> — <code>MiddlewareConfig</code> (env-driven: <code>REQUEST_TIMEOUT_SECS</code>, <code>MAX_CONCURRENT_REQUESTS</code>, <code>RATE_LIMIT_BURST</code>, <code>RATE_LIMIT_PERIOD_MS</code>) plus <code>apply_common_middlewares</code>, which layers, outer to inner: CORS, <code>tower_governor</code>&#39;s per-IP token-bucket <code>GovernorLayer</code> (429 on excess — its per-key state is pruned every 60s via <code>limiter.retain_recent()</code> so it doesn&#39;t grow unbounded over the process lifetime), a conditional- GET middleware for the download route (<code>ETag</code>/<code>If-None-Match</code>/<code>304</code>, computed directly from the requested key without touching storage), a <code>Semaphore</code>-backed saturation/timeout guard (503 on either), and <code>tower-http</code>&#39;s <code>CompressionLayer</code> (br/deflate/gzip/zstd) closest to the app.</li></ul><h2 id="api-handlers-—-src-modules-api" tabindex="-1">API handlers — <code>src/modules/api/</code> <a class="header-anchor" href="#api-handlers-—-src-modules-api" aria-label="Permalink to “API handlers — src/modules/api/”">​</a></h2><ul><li><strong><code>handler.rs</code></strong> — <code>ApiService</code>, the shared application state: <code>resize_service</code>, <code>signing</code>, <code>presets</code>/<code>allowed_options</code> (issue #52), and (under <code>otel</code>) <code>metrics_auth</code>. <code>ApiService::create</code> builds every sub-config from <code>EnvConfig</code> and fails closed at startup for signing, <code>/metrics</code> auth, and preset parsing — a misconfiguration is a boot-time error, not a per-request surprise.</li><li><strong><code>resize.rs</code></strong> — <code>GET /{signature}/{processing_options}/{plain|base64 source}.{extension}</code>. Splits the path (<code>modules::url::split</code>), verifies the signature, parses options+source (<code>SignedRequest::parse_with_config</code>), resolves <code>.auto</code> via <code>modules::negotiation::resolve</code>, calls <code>ResizeService::resize</code>, and builds an explicit <code>301</code> (not axum&#39;s <code>Redirect::permanent</code>, which issues <code>308</code>) with <code>Cache-Control: public, max-age=31536000, immutable</code> and, only for a negotiated <code>.auto</code> request, <code>Vary: Accept</code>.</li><li><strong><code>download.rs</code></strong> — <code>GET /api/images/files/{key}</code>, deliberately unsigned (this route only ever serves bytes the resize route already produced and cached under a content-derived key; the strict key grammar in <code>services::storage::key_validation</code> is the guard here, not a signature). Derives <code>Content-Type</code> from the key&#39;s own extension.</li></ul><h2 id="url-grammar-and-signing" tabindex="-1">URL grammar and signing <a class="header-anchor" href="#url-grammar-and-signing" aria-label="Permalink to “URL grammar and signing”">​</a></h2><h3 id="src-modules-url" tabindex="-1"><code>src/modules/url/</code> <a class="header-anchor" href="#src-modules-url" aria-label="Permalink to “src/modules/url/”">​</a></h3><p>Implements the imgproxy-compatible signed-URL grammar <code>/{signature}/{processing_options}/{plain|base64 source}.{extension}</code>:</p><ul><li><strong><code>mod.rs</code></strong> — <code>split</code> (cheap extraction of the signature segment and the exact signed byte string, run before any full parse so an unauthenticated caller can&#39;t use parse-error content as an oracle) and <code>SignedRequest::parse</code>/<code>parse_with_config</code> (full options+source grammar, presets and the processing-option allowlist applied ahead of the plain grammar parse).</li><li><strong><code>options.rs</code></strong> — <code>ProcessingOptions</code>, parsing <code>/</code>-delimited <code>code:arg1:arg2</code> segments (<code>rs</code>, <code>q</code>, <code>bl</code>, <code>g</code>, <code>el</code>, <code>bg</code>, <code>ar</code>, <code>sm</code> (strip-metadata, default <code>true</code> — issue #5), <code>fq</code>, <code>webpo</code>, <code>jpgo</code>/<code>mb</code> (JPEG progressive/chroma-subsampling tuning and max-bytes search — issue #76), crop/gravity, rotate/flip/trim/extend/padding/zoom/dpr/min-width/min-height, watermark, preset references).</li><li><strong><code>presets.rs</code></strong> — <code>PresetRegistry</code> (parses the <code>PRESETS</code> env var: named, reusable option-segment lists, imgproxy-compatible; a preset named <code>default</code> is auto-prepended to every request) and <code>AllowedOptions</code> (parses <code>ALLOWED_PROCESSING_OPTIONS</code>, an allowlist of which option codes a deployment permits at the top level of a URL).</li><li><strong><code>source.rs</code></strong> — <code>SourceSpec</code>/<code>parse_source</code>: either <code>plain/{percent-encoded URL}.{extension}</code> or a single base64url-encoded segment, with the trailing <code>.{extension}</code> mandatory and mapped to <code>ImageFormat</code> (including the <code>.auto</code> negotiation trigger).</li></ul><h3 id="src-modules-signing" tabindex="-1"><code>src/modules/signing/</code> <a class="header-anchor" href="#src-modules-signing" aria-label="Permalink to “src/modules/signing/”">​</a></h3><ul><li><strong><code>verify.rs</code></strong> — <code>compute_signature</code>/<code>verify_signature</code>/<code>sign</code>: <code>HMAC-SHA256(key, salt || signed_path)</code>, base64url (no padding), constant-time comparison via the <code>subtle</code> crate.</li><li><strong><code>config.rs</code></strong> — <code>SigningConfig::from_env</code>, which fails closed at startup (issue #27): a deployment must either configure a real key/salt or explicitly set <code>ALLOW_UNSIGNED_REQUESTS=true</code> to use the <code>/unsigned/...</code> escape hatch.</li></ul><h3 id="src-modules-negotiation-rs" tabindex="-1"><code>src/modules/negotiation.rs</code> <a class="header-anchor" href="#src-modules-negotiation-rs" aria-label="Permalink to “src/modules/negotiation.rs”">​</a></h3><p><code>resolve(format, accept)</code> — resolves <code>ImageFormat::Auto</code> against the request&#39;s <code>Accept</code> header: AVIF first (17-32% smaller than JPEG at matched quality, per <code>adr/0006</code>), then WebP — not because it&#39;s smaller (the two are roughly on par now) but because it&#39;s the only alpha-capable option for a client that accepts WebP but not AVIF — falling back to JPEG, weighted by each entry&#39;s <code>q</code> parameter. Any non-<code>Auto</code> format passes through unchanged with <code>negotiated = false</code>.</p><h3 id="src-modules-metrics-auth" tabindex="-1"><code>src/modules/metrics_auth/</code> <a class="header-anchor" href="#src-modules-metrics-auth" aria-label="Permalink to “src/modules/metrics_auth/”">​</a></h3><p>Bearer-token authentication for <code>GET /metrics</code> (issue #77), gated behind the <code>otel</code> feature since that&#39;s the only build where <code>/metrics</code> is ever mounted at all. <code>MetricsAuthConfig::from_env</code> fails closed at startup, mirroring <code>SigningConfig</code>.</p><h2 id="services-—-src-services" tabindex="-1">Services — <code>src/services/</code> <a class="header-anchor" href="#services-—-src-services" aria-label="Permalink to “Services — src/services/”">​</a></h2><h3 id="resize-handler-rs-—-resizeservice" tabindex="-1"><code>resize/handler.rs</code> — <code>ResizeService</code> <a class="header-anchor" href="#resize-handler-rs-—-resizeservice" aria-label="Permalink to “resize/handler.rs — ResizeService”">​</a></h3><p>The orchestrator tying cache, image processing, and storage together:</p><ul><li><code>resize(params)</code> — generates the cache key, checks the cache, and on a miss runs single-flight coalescing before calling <code>do_resize_work</code>. See <code>overview.md</code>&#39;s &quot;Concurrency model&quot; and its cache-miss sequence diagram for the full mechanics of <code>InFlightMap</code>/<code>InFlightGuard</code> (issue #37).</li><li><code>do_resize_work</code> — the actual download → process → upload pipeline for a confirmed miss.</li><li><code>download(params)</code> — serves the unsigned <code>/api/images/files/{key}</code> route by reading directly from storage; a missing/expired key surfaces as a &quot;not found&quot; message that <code>AppError::classify_download_error</code> maps to <code>404</code>.</li><li><code>resize_batch</code> — bounded-concurrency batch resizing over <code>futures::stream::buffer_unordered</code>.</li></ul><h3 id="image-handler-rs-—-imageservice" tabindex="-1"><code>image/handler.rs</code> — <code>ImageService</code> <a class="header-anchor" href="#image-handler-rs-—-imageservice" aria-label="Permalink to “image/handler.rs — ImageService”">​</a></h3><p>Owns the two semaphores (<code>download_semaphore</code>, <code>processing_semaphore</code>), the SSRF-guarded fetch path, and the decode/resize/encode pipeline:</p><ul><li><code>fetch_validated</code>/<code>download_image</code> — see <code>overview.md</code>&#39;s &quot;Security boundary&quot; section for the SSRF guard itself (implemented in <code>source_guard.rs</code>, described next). <code>download_image</code> also enforces the streaming size cap.</li><li><code>process_image</code> — acquires <code>processing_semaphore</code> (non-blocking <code>try_acquire_owned</code>, <code>503</code> on exhaustion) and runs decode/resize/encode on <code>spawn_blocking</code>, with a <code>tx.is_closed()</code> check to skip queued-but-not-yet-started work when the caller has already disconnected.</li><li><code>process_image_blocking_with_limits*</code> — header-only dimension peek and resolution check (decompression-bomb guard) before any full decode; EXIF autorotate, trim, and explicit crop are applied in that order (matching imgproxy&#39;s own pipeline ordering) before the actual resize; animated GIF/WebP sources are detected and routed to <code>encode_animation</code> separately.</li><li><code>decode_with_limits</code> — dispatches by source format, each with a fallback to the plain <code>image</code>-crate decoder (<code>decode_with_image_crate</code>) on failure: <ul><li><strong>JPEG</strong> — <code>decode_jpeg_scaled</code> (<code>jpeg-decoder</code>&#39;s <code>Decoder::scale()</code>, DCT-scaled when a resize makes a smaller decode safe, full-size otherwise; issue #67, backend swapped from mozjpeg/libjpeg-turbo to pure Rust by #134).</li><li><strong>WebP</strong> — the WebP decode path (issue #66, backend swapped from real libwebp via FFI to <a href="https://github.com/vaam-apps/vaam-image-webp" target="_blank" rel="noreferrer"><code>vaam-image-webp</code></a> by #134) — replaces the <code>image</code> crate&#39;s pure-Rust <code>image-webp</code> decoder.</li><li><strong>AVIF</strong> — <code>avif_codec::decode</code> (<code>avif-decode</code>/<code>rav1d</code>, issue #67/#68, backend swapped from <code>libavif</code>/dav1d to pure Rust by #134) — the first release where AVIF is accepted as a <em>source</em> format at all; previously any <code>.avif</code> source was rejected outright.</li><li><strong>PNG/GIF</strong> — always <code>decode_with_image_crate</code> (the <code>image</code> crate&#39;s own decoders); untouched by the above.</li></ul></li><li><code>encode_with_max_bytes</code> — binary-searches JPEG quality down until encoded output fits a requested <code>max_bytes</code> budget (issue #76), bounded to a fixed number of extra encode attempts.</li></ul><h3 id="image-avif-codec-rs" tabindex="-1"><code>image/avif_codec.rs</code> <a class="header-anchor" href="#image-avif-codec-rs" aria-label="Permalink to “image/avif_codec.rs”">​</a></h3><p>AVIF encode and decode via pure-Rust crates, both directions (issue #67/#68; backend swapped from <code>libavif</code> (AOM + dav1d, vendored C) to pure Rust by #134): <code>encode</code> (<code>ravif</code>/<code>rav1e</code>, <code>DEFAULT_AVIF_SPEED = 6</code>) and <code>decode</code>/<code>peek_dimensions</code> (<code>avif-decode</code>/<code>rav1d</code>, the latter re-running the same megapixel-overflow-checked resolution guard <code>ImageService::check_source_resolution</code> does, as defense in depth around the container parse). On the encode side this is a return to <code>ravif</code>/<code>rav1e</code>, which <code>libavif</code>/AOM had replaced (<code>adr/0004</code>, <code>adr/0005</code>) before #67/#68 shipped; #134&#39;s motivation is removing every C/C++ dependency, not a re-run of that quality/speed comparison — see the <code>ravif</code>/<code>avif-decode</code> dependency comments in <code>Cargo.toml</code>. AVIF source decode itself is unaffected by #134: this service previously had no decode path at all before #67/#68 added one.</p><h3 id="image-source-guard-rs" tabindex="-1"><code>image/source_guard.rs</code> <a class="header-anchor" href="#image-source-guard-rs" aria-label="Permalink to “image/source_guard.rs”">​</a></h3><p>Pure, deterministic SSRF validation logic (the one exception is <code>resolve_validated_addr</code>, which performs the actual DNS lookup): <code>validate_scheme</code>, <code>is_allowed_source</code>/<code>matches_allowed_prefix</code>, <code>is_blocked_ip_with_policy</code> (and its IPv4/IPv6 halves), and IPv4-literal decoding covering decimal/octal/hex smuggling forms. See <code>overview.md</code>&#39;s &quot;Security boundary&quot; for the full threat model this covers and why redirect revalidation and DNS pinning are both necessary.</p><h3 id="cache-handler-rs-—-cacheservice" tabindex="-1"><code>cache/handler.rs</code> — <code>CacheService</code> <a class="header-anchor" href="#cache-handler-rs-—-cacheservice" aria-label="Permalink to “cache/handler.rs — CacheService”">​</a></h3><p><code>generate_key(params)</code> — the SHA-256, length-prefixed, versioned cache key described in <code>overview.md</code>&#39;s &quot;Cache key design&quot;. <code>CACHE_KEY_VERSION</code> is currently <code>11</code>; its doc comment on this file is the authoritative history of what each version bump added — including v10 (metadata-strip default, issue #5), v11 (the AVIF encoder cutover to <code>libavif</code>/AOM) — and, in one case (issue #67&#39;s WebP decoder swap to libwebp), why a bump was deliberately <em>not</em> taken.</p><h3 id="storage" tabindex="-1"><code>storage/</code> <a class="header-anchor" href="#storage" aria-label="Permalink to “storage/”">​</a></h3><ul><li><strong><code>core.rs</code></strong> — the <code>StorageBackend</code> trait: <code>upload_image</code>/<code>upload_image_with_ttl</code>, <code>check_cache</code>, <code>get_image</code>, <code>delete</code>. <code>ttl: None</code> means &quot;never expires.&quot;</li><li><strong><code>handler.rs</code></strong> — <code>StorageService</code>/<code>StorageConfig</code>/<code>StorageType</code>, selecting a backend by Cargo feature and (when more than one is compiled in) <code>STORAGE_TYPE</code>. Also enforces that a configured <code>key_prefix</code> (from <code>STORAGE_SUB_PATH</code>) matches what <code>CacheService::generate_key</code> actually produces.</li><li><strong><code>s3_handler.rs</code></strong> (feature <code>s3</code>) — S3/MinIO-compatible backend via <code>aws-sdk-s3</code>.</li><li><strong><code>local_fs_handler.rs</code></strong> (feature <code>local_fs</code>) — local-directory backend.</li><li><strong><code>in_memory_handler.rs</code></strong> (feature <code>in_memory</code>, test-only) — unbounded <code>HashMap</code>-backed backend, <code>#[cfg(all(test, feature = &quot;in_memory&quot;))]</code> — does not exist in a release build at all, regardless of the Cargo feature flag; selecting it via <code>STORAGE_TYPE</code> outside tests fails fast at startup instead of running an uncapped cache in production.</li><li><strong><code>key_validation.rs</code></strong> — <code>validate_cache_key</code>, the strict grammar (<code>&lt;prefix&gt;&lt;64 lowercase hex&gt;.&lt;jpg|png|webp|avif|gif&gt;</code>) every backend is checked against before a key ever reaches it, closing path-traversal and S3 IDOR in one place rather than per backend.</li></ul><h3 id="health-handler-rs" tabindex="-1"><code>health/handler.rs</code> <a class="header-anchor" href="#health-handler-rs" aria-label="Permalink to “health/handler.rs”">​</a></h3><p><code>health()</code> — returns the literal string <code>&quot;OK&quot;</code>. Deliberately unauthenticated; see <code>overview.md</code>&#39;s &quot;Security boundary&quot; for why.</p><h3 id="metrics-handler-rs" tabindex="-1"><code>metrics/handler.rs</code> <a class="header-anchor" href="#metrics-handler-rs" aria-label="Permalink to “metrics/handler.rs”">​</a></h3><p><code>metrics_handler()</code> — encodes the global Prometheus registry (<code>prometheus::gather()</code>) as text. Only compiled/mounted under the <code>otel</code> feature; protected by <code>modules::metrics_auth</code> at the router layer, not in this handler itself.</p><h2 id="models-—-src-models-params-rs" tabindex="-1">Models — <code>src/models/params.rs</code> <a class="header-anchor" href="#models-—-src-models-params-rs" aria-label="Permalink to “Models — src/models/params.rs”">​</a></h2><p><code>ResizeQuery</code> (the fully-parsed representation of a resize request — url, width/height, <code>ResizeType</code>, <code>ImageFormat</code>, quality/format-quality overrides, crop/gravity, geometry operations, watermark, etc.) and <code>DownloadPathParams</code> (<code>{ key: String }</code>, hand-written — see &quot;Removed&quot; below).</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><ul><li><strong><code>src/modules/env/env.rs</code></strong> — <code>EnvConfig</code>, the <code>envconfig</code>-derived top-level environment binding (HTTP host/port, storage credentials, <code>MAX_IMAGE_SIZE_MB</code>, <code>MAX_SRC_RESOLUTION_MP</code>, <code>ALLOWED_SOURCES</code>, <code>ALLOW_LOOPBACK_SOURCE_ADDRESSES</code>/<code>ALLOW_LINK_LOCAL_SOURCE_ADDRESSES</code>, <code>max_redirects</code>, presets/allowlist strings, etc.).</li><li><strong><code>src/config/performance.rs</code></strong> — <code>PerformanceConfig</code>, derived from <code>EnvConfig</code> plus a small set of named default profiles (default/high-throughput/low-latency/memory-constrained), each setting <code>max_image_size</code>, <code>max_src_resolution_mp</code>, <code>max_redirects</code>, download/processing concurrency limits, and the SSRF-guard override flags.</li></ul><h2 id="utility-modules-—-src-modules-utils" tabindex="-1">Utility modules — <code>src/modules/utils/</code> <a class="header-anchor" href="#utility-modules-—-src-modules-utils" aria-label="Permalink to “Utility modules — src/modules/utils/”">​</a></h2><ul><li><strong><code>date.rs</code></strong> — a minimal hand-rolled RFC 7231 <code>IMF-fixdate</code> formatter (no date/time crate is a dependency of this crate), used for the download route&#39;s <code>Last-Modified</code> header.</li><li><strong><code>etag.rs</code></strong> — <code>if_none_match_satisfied</code>, RFC 7232 §3.2 strong-comparison matching against the single server-computed <code>ETag</code> the conditional-download middleware produces.</li><li><strong><code>err.rs</code></strong> — <code>AppError</code> and its <code>classify_download_error</code>/<code>classify_resize_error</code> constructors, mapping internal failures to HTTP status codes (see <code>overview.md</code>&#39;s rejection-state diagram for the concrete mapping). Every variant renders with <code>Cache-Control: no-store</code>.</li><li><strong><code>cgroup.rs</code></strong> — <code>effective_cpu_count</code>, reading cgroup v2 <code>cpu.max</code> or cgroup v1 <code>cpu.cfs_quota_us</code>/<code>cpu.cfs_period_us</code> directly (falling back to <code>num_cpus::get()</code>), used by <code>main.rs</code> to size the Tokio runtime.</li></ul><h2 id="tracing-—-src-modules-tracer" tabindex="-1">Tracing — <code>src/modules/tracer/</code> <a class="header-anchor" href="#tracing-—-src-modules-tracer" aria-label="Permalink to “Tracing — src/modules/tracer/”">​</a></h2><p>OpenTelemetry tracing/metrics initialization (<code>init.rs</code>), compiled only under the <code>otel</code> feature.</p><h2 id="removed-since-the-last-documentation-pass" tabindex="-1">Removed since the last documentation pass <a class="header-anchor" href="#removed-since-the-last-documentation-pass" aria-label="Permalink to “Removed since the last documentation pass”">​</a></h2><p>The following existed in an earlier version of this service and no longer do. They are recorded here only as history, not as current architecture:</p><ul><li><strong>The generated OpenAPI server</strong> (<code>gen-server</code>, a <code>packages/</code> directory, <code>openapi.yaml</code>). Issue #53 replaced it with the hand-written router in <code>src/modules/router/router.rs</code> and the hand-written handlers in <code>src/modules/api/</code>. Verified: <code>grep -rc &#39;gen-server\\|gen_server\\|openapi&#39; Cargo.toml</code> and <code>find . -iname &#39;openapi.yaml&#39;</code> both return nothing in this tree.</li><li><strong><code>rayon</code></strong> — the old CPU-bound processing pool. Replaced by <code>tokio::task::spawn_blocking</code> bounded by <code>processing_semaphore</code>; see <code>image/handler.rs</code>&#39;s doc comment on <code>process_image</code> for why rayon&#39;s intra-job work-stealing was never actually used. Not a dependency in <code>Cargo.toml</code>.</li><li><strong><code>o2o</code></strong>, <strong><code>lru</code></strong>, <strong><code>axum-extra</code></strong> — none appear in <code>Cargo.toml</code>&#39;s dependency list; no code under <code>src/</code> references them.</li></ul>`,51)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};